using System;
using System.Collections.Generic;
using UnityEngine;

namespace ScrapTitan.Data
{
    /// <summary>
    /// The one way into the game's content. Generated by the editor importer from the JSON in
    /// src/data, and loaded at runtime from Resources so nothing has to carry a reference to it.
    ///
    /// Adding a level or an enemy means adding JSON and re-importing. No code change.
    /// </summary>
    public sealed class GameDatabase : ScriptableObject
    {
        public const string ResourcePath = "ScrapTitanDatabase";

        [Tooltip("Set by the importer. Which commit of src/data these assets were built from.")]
        public string importedFromRevision;

        public string importedAtUtc;

        public EnemyDef[] enemies = Array.Empty<EnemyDef>();
        public WeaponDef[] weapons = Array.Empty<WeaponDef>();
        public PilotDef[] pilots = Array.Empty<PilotDef>();
        public EscortDef[] escorts = Array.Empty<EscortDef>();

        [Tooltip("In level order, level-01 first.")]
        public LevelDef[] levels = Array.Empty<LevelDef>();

        public TuningDef tuning;

        private Dictionary<string, EnemyDef> enemyById;
        private Dictionary<string, WeaponDef> weaponById;
        private Dictionary<string, LevelDef> levelById;
        private Dictionary<string, EscortDef> escortById;
        private Dictionary<string, PilotDef> pilotById;

        private static GameDatabase loaded;

        /// <summary>The database, loaded from Resources on first use.</summary>
        public static GameDatabase Instance
        {
            get
            {
                if (loaded == null)
                {
                    loaded = Resources.Load<GameDatabase>(ResourcePath);
                    if (loaded == null)
                    {
                        throw new InvalidOperationException(
                            $"No GameDatabase at Resources/{ResourcePath}. "
                            + "Run Scrap Titan > Import data from src/data.");
                    }
                }
                return loaded;
            }
        }

        private void OnDisable()
        {
            // Dropped so a re-import inside the editor is picked up rather than cached.
            enemyById = null;
            weaponById = null;
            levelById = null;
            escortById = null;
            pilotById = null;
        }

        public EnemyDef Enemy(string id) => Lookup(ref enemyById, enemies, static e => e.id, id, "enemy");

        public WeaponDef Weapon(string id) => Lookup(ref weaponById, weapons, static w => w.id, id, "weapon");

        public LevelDef Level(string id) => Lookup(ref levelById, levels, static l => l.id, id, "level");

        public EscortDef Escort(string id) => Lookup(ref escortById, escorts, static e => e.id, id, "escort");

        public PilotDef Pilot(string id) => Lookup(ref pilotById, pilots, static p => p.id, id, "pilot");

        public bool TryGetEnemy(string id, out EnemyDef result)
        {
            BuildIndex(ref enemyById, enemies, static e => e.id);
            return enemyById.TryGetValue(id ?? string.Empty, out result);
        }

        private static T Lookup<T>(ref Dictionary<string, T> index, T[] all, Func<T, string> idOf,
                                   string id, string what) where T : ScriptableObject
        {
            BuildIndex(ref index, all, idOf);
            if (id != null && index.TryGetValue(id, out T found)) return found;
            throw new KeyNotFoundException($"No {what} with id '{id}'. Known: {string.Join(", ", index.Keys)}");
        }

        private static void BuildIndex<T>(ref Dictionary<string, T> index, T[] all, Func<T, string> idOf)
        {
            if (index != null) return;
            index = new Dictionary<string, T>(all.Length, StringComparer.Ordinal);
            foreach (T item in all)
            {
                if (item == null) continue;
                index[idOf(item)] = item;
            }
        }
    }
}
